import React from 'react';
import { Bell, X, TrendingDown, Megaphone, CheckCheck, ExternalLink, RefreshCw, ArrowRight } from 'lucide-react';
import { useApp } from '../context/AppContext';

/**
 * Notifications drawer — one hub, two producers:
 *   price_drop  auto-generated by Try1second when a VERIFIED live price for a
 *               tracked product hits the user's target (real prices only)
 *   admin       announcements pushed from Admin → Notifications
 * Below the feed, the user's active watchlist stays visible for context.
 */
export const NotificationsDrawer: React.FC = () => {
  const {
    isNotificationsOpen,
    setIsNotificationsOpen,
    items,
    trackedItemIds,
    setVertical,
    setActiveNavTab,
    notifications,
    unreadNotificationCount,
    isFetchingNotifications,
    refreshNotifications,
    markNotificationsRead,
    openProductPage,
    authUser,
  } = useApp();

  if (!isNotificationsOpen) return null;

  const trackedItems = items.filter((it) => trackedItemIds.includes(it.id));

  const timeAgo = (iso: string | null) => {
    if (!iso) return 'just now';
    const t = new Date(iso).getTime();
    if (!Number.isFinite(t)) return 'recently';
    const mins = Math.max(1, Math.round((Date.now() - t) / 60000));
    if (mins < 60) return `${mins}m ago`;
    const hrs = Math.round(mins / 60);
    if (hrs < 24) return `${hrs}h ago`;
    return `${Math.round(hrs / 24)}d ago`;
  };

  const handleOpenNotification = async (n: any) => {
    await markNotificationsRead(n.id);
    setIsNotificationsOpen(false);
    if (n.searchQuery) {
      openProductPage({ query: n.searchQuery });
    } else if (n.ctaUrl) {
      window.open(n.ctaUrl, '_blank', 'noopener,noreferrer');
    }
  };

  const handleOpenItem = (vertical: any) => {
    setVertical(vertical);
    setActiveNavTab('compare');
    setIsNotificationsOpen(false);
  };

  return (
    <div className="fixed inset-0 z-50 flex justify-end bg-slate-900/50 backdrop-blur-2xs animate-in fade-in duration-150">
      <div className="w-full max-w-sm bg-white h-full shadow-2xl flex flex-col p-5 border-l border-slate-200 overflow-y-auto">
        {/* Header */}
        <div className="flex items-center justify-between pb-4 border-b border-slate-100">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-lg bg-red-50 text-red-600 flex items-center justify-center">
              <Bell className="w-4 h-4" />
            </div>
            <div>
              <h3 className="text-sm font-bold text-slate-900">Notifications</h3>
              <span className="text-[11px] text-slate-500">
                {unreadNotificationCount > 0 ? `${unreadNotificationCount} new` : 'All caught up'} · {trackedItems.length} tracked
              </span>
            </div>
          </div>

          <div className="flex items-center gap-1">
            <button
              type="button"
              onClick={() => void refreshNotifications()}
              className="p-1.5 text-slate-400 hover:text-slate-700 rounded-lg hover:bg-slate-100 transition-colors cursor-pointer"
              title="Refresh"
            >
              <RefreshCw className={`w-4 h-4 ${isFetchingNotifications ? 'animate-spin' : ''}`} />
            </button>
            {notifications.length > 0 && (
              <button
                type="button"
                onClick={() => void markNotificationsRead()}
                className="p-1.5 text-slate-400 hover:text-slate-700 rounded-lg hover:bg-slate-100 transition-colors cursor-pointer"
                title="Mark all as read"
              >
                <CheckCheck className="w-4 h-4" />
              </button>
            )}
            <button
              type="button"
              onClick={() => setIsNotificationsOpen(false)}
              className="p-1.5 text-slate-400 hover:text-slate-700 rounded-lg hover:bg-slate-100 transition-colors cursor-pointer"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>

        {/* Notification feed */}
        <div className="mt-4 space-y-2.5">
          <span className="text-[11px] font-bold uppercase tracking-wider text-slate-400 block">
            Latest for you
          </span>

          {notifications.length === 0 && !isFetchingNotifications && (
            <div className="p-4 rounded-xl border border-slate-100 bg-slate-50/70 text-center">
              <p className="text-xs text-slate-500 leading-relaxed">
                No notifications yet. Track a product on its page and we'll alert you here the moment
                a live, verified price hits your target.
              </p>
            </div>
          )}

          {isFetchingNotifications && notifications.length === 0 && (
            <div className="p-4 rounded-xl border border-slate-100 bg-slate-50/70 text-center">
              <p className="text-xs text-slate-500">Loading notifications…</p>
            </div>
          )}

          {notifications.map((n) => (
            <button
              key={n.id}
              type="button"
              onClick={() => void handleOpenNotification(n)}
              className={`w-full text-left p-3 rounded-xl border transition-colors cursor-pointer flex gap-2.5 ${
                n.read
                  ? 'border-slate-100 bg-white hover:bg-slate-50'
                  : 'border-red-200 bg-red-50/60 hover:bg-red-50'
              }`}
            >
              {/* Thumbnail: real product image or kind icon */}
              {n.image ? (
                <img
                  src={n.image}
                  alt=""
                  className="w-11 h-11 rounded-lg object-cover bg-slate-100 border border-slate-100 shrink-0"
                  loading="lazy"
                  onError={(e) => { (e.target as HTMLImageElement).style.display = 'none'; }}
                />
              ) : (
                <div className={`w-11 h-11 rounded-lg flex items-center justify-center shrink-0 ${n.kind === 'price_drop' ? 'bg-emerald-50 text-emerald-600' : 'bg-slate-100 text-slate-600'}`}>
                  {n.kind === 'price_drop' ? <TrendingDown className="w-5 h-5" /> : <Megaphone className="w-5 h-5" />}
                </div>
              )}

              <div className="min-w-0 flex-1">
                <div className="flex items-start justify-between gap-2">
                  <span className="text-[10px] font-extrabold uppercase tracking-wider text-slate-400 shrink-0">
                    {n.kind === 'price_drop' ? (
                      <span className="text-emerald-700">Price Drop</span>
                    ) : (
                      'Announcement'
                    )}
                  </span>
                  <span className="text-[10px] text-slate-400 shrink-0">{timeAgo(n.createdAt)}</span>
                </div>

                <p className={`text-xs leading-snug mt-0.5 ${n.read ? 'font-semibold text-slate-800' : 'font-bold text-slate-900'}`}>
                  {n.title}
                </p>
                <p className="text-[11px] text-slate-500 leading-snug mt-0.5 line-clamp-2">{n.body}</p>

                {n.priceNow != null && (
                  <p className="mt-1 text-xs font-mono font-bold text-emerald-700">
                    ₹{n.priceNow.toLocaleString('en-IN')}
                    {n.seller ? <span className="font-sans font-semibold text-slate-500"> · {n.seller}</span> : null}
                  </p>
                )}

                <span className="mt-1 inline-flex items-center gap-1 text-[11px] font-bold text-red-600">
                  {n.searchQuery ? 'Open product' : 'Open link'}
                  {n.searchQuery ? <ArrowRight className="w-3 h-3" /> : <ExternalLink className="w-3 h-3" />}
                </span>
              </div>

              {!n.read && <span className="w-2 h-2 rounded-full bg-red-600 shrink-0 mt-1" />}
            </button>
          ))}

          {!authUser && (
            <p className="text-[10px] text-slate-400 text-center pt-1">
              Sign in to get your own price-drop notifications synced across devices.
            </p>
          )}
        </div>

        {/* Active watchlist (context under the feed) */}
        {trackedItems.length > 0 && (
          <div className="mt-4 pt-3 border-t border-slate-100 space-y-2.5">
            <span className="text-[11px] font-bold uppercase tracking-wider text-slate-400 block">
              Active Watchlist
            </span>

            {trackedItems.slice(0, 5).map((item) => (
              <div
                key={item.id}
                className="p-3 rounded-xl border border-slate-100 bg-slate-50/70 hover:bg-slate-100/70 transition-colors"
              >
                <div className="flex items-center justify-between text-[11px] mb-1">
                  <span className="font-extrabold uppercase text-slate-400">
                    {item.vertical}
                  </span>
                  <span className="text-emerald-700 font-bold bg-emerald-50 px-1.5 py-0.2 rounded-sm flex items-center gap-0.5">
                    <TrendingDown className="w-3 h-3 text-emerald-600" />
                    Tracking Active
                  </span>
                </div>

                <h4 className="text-xs font-bold text-slate-900 leading-tight">
                  {item.title}
                </h4>

                <div className="mt-2 flex items-center justify-between">
                  <span className="font-mono font-bold text-xs text-slate-900">
                    ₹{item.primaryPrice.toLocaleString('en-IN')}
                  </span>

                  <button
                    type="button"
                    onClick={() => handleOpenItem(item.vertical)}
                    className="text-[11px] font-bold text-red-600 hover:underline flex items-center gap-0.5 cursor-pointer"
                  >
                    <span>View Deal</span>
                    <ArrowRight className="w-3 h-3" />
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}

      </div>
    </div>
  );
};
